{
  "status": "ok",
  "data": {
    "as_of": "2019-08-08",
    "lookback_days": 365,
    "n_entries_total": 53,
    "n_entries_visible": 26,
    "entries": [
      {
        "entry_date": "2018-08-23",
        "body": "List 2 tariffs take effect: US 25% on ~$16B (completing the $50B package). China imposes matching ~$16B retaliation."
      },
      {
        "entry_date": "2018-09-17",
        "body": "Trump directs USTR to finalize List 3: 10% tariffs on ~$200B of Chinese imports effective Sept 24, scheduled to rise to 25% on Jan 1, 2019."
      },
      {
        "entry_date": "2018-09-18",
        "body": "USTR publishes the finalized List 3 (5,745 lines after removing some consumer/electronics and other products from the July proposal)."
      },
      {
        "entry_date": "2018-09-24",
        "body": "List 3 takes effect at 10%. China imposes retaliatory tariffs (5–10%) on ~$60B of US goods. Combined US Section 301 coverage now ~$250B of Chinese imports."
      },
      {
        "entry_date": "2018-11-01",
        "body": "Trump and Xi hold a phone call focused on trade; agree to meet at the G20 in Argentina."
      },
      {
        "entry_date": "2018-12-01",
        "body": "G20 Buenos Aires dinner: Trump and Xi agree to a 90-day negotiation window. Planned Jan 1, 2019 hike of List 3 from 10% to 25% is suspended (tariffs remain at 10%). Same day: Canada arrests Huawei CFO Meng Wanzhou in Vancouver on a US provisional extradition request. China demands her release."
      },
      {
        "entry_date": "2018-12-10",
        "body": "China detains Canadians Michael Kovrig and Michael Spavor (widely viewed as retaliation for the Meng arrest; Beijing denies linkage)."
      },
      {
        "entry_date": "2019-01-07",
        "body": "Trade talks resume in Beijing (working / mid-level). China discusses increased purchases of US goods; structural issues remain open."
      },
      {
        "entry_date": "2019-01-28",
        "body": "US DOJ unseals fraud and sanctions-related charges against Huawei and Meng; US formally requests Meng's extradition from Canada (deadline under Canadian law was Jan 30)."
      },
      {
        "entry_date": "2019-01-30",
        "body": "Lighthizer and Mnuchin in Beijing for high-level talks. Purchase commitments discussed; enforcement and structural IP/tech-transfer issues unresolved."
      },
      {
        "entry_date": "2019-02-14",
        "body": "Another round of talks (through Feb 15). Progress reported on purchases; enforcement mechanism still disputed."
      },
      {
        "entry_date": "2019-02-24",
        "body": "Trump tweets that talks have made substantial progress and further delays the scheduled List 3 hike from 10% to 25% (previously tied to the March 1 end of the 90-day window)."
      },
      {
        "entry_date": "2019-03-01",
        "body": "The original 90-day tariff-hike deadline passes without an increase (already delayed on Feb 24)."
      },
      {
        "entry_date": "2019-04-03",
        "body": "Intensive Washington talks between US and Chinese negotiators; both sides report progress on text, including enforcement language. No final deal signed."
      },
      {
        "entry_date": "2019-05-05",
        "body": "Trump tweets that negotiations are going \"too slowly\" and that China is attempting to \"renegotiate.\" Orders List 3 raised from 10% to 25% on May 10 and directs preparation of tariffs on remaining Chinese imports (~$300B)."
      },
      {
        "entry_date": "2019-05-10",
        "body": "List 3 tariff rate rises from 10% to 25%."
      },
      {
        "entry_date": "2019-05-13",
        "body": "China announces it will raise retaliatory tariff rates on its ~$60B US-goods list (higher rates phased in; many effective June 1)."
      },
      {
        "entry_date": "2019-05-15",
        "body": "Trump signs Executive Order 13873 (securing information/communications technology supply chains). Commerce moves to restrict Huawei."
      },
      {
        "entry_date": "2019-05-16",
        "body": "US Commerce Department adds Huawei and affiliates to the Entity List. US firms generally barred from selling to Huawei without a license."
      },
      {
        "entry_date": "2019-05-20",
        "body": "Google suspends Huawei's access to Android updates / GMS; major US chip suppliers pause sales. Same day: Xi Jinping visits a rare-earth facility in Jiangxi (widely read as a signal on rare-earth leverage)."
      },
      {
        "entry_date": "2019-05-31",
        "body": "China announces it will establish an \"unreliable entity list\" targeting foreign firms that cut supplies to Chinese companies for non-commercial reasons."
      },
      {
        "entry_date": "2019-06-18",
        "body": "Trump and Xi agree by phone to meet at the G20 in Osaka."
      },
      {
        "entry_date": "2019-06-29",
        "body": "G20 Osaka: Trump and Xi agree to resume talks. Existing tariffs remain; no new tariffs \"for the time being.\" Trump says he will ease some Huawei restrictions (Huawei remains on the Entity List; scope of any relief later unclear)."
      },
      {
        "entry_date": "2019-07-30",
        "body": "Trade talks in Shanghai (through July 31). Little progress reported."
      },
      {
        "entry_date": "2019-08-01",
        "body": "After the Shanghai round, Trump announces 10% tariffs on the remaining ~$300B of Chinese goods (List 4), effective Sept 1."
      },
      {
        "entry_date": "2019-08-05",
        "body": "After CNY breaks 7 per USD, US Treasury designates China a currency manipulator (first such designation since 1994)."
      }
    ]
  }
}

